from itertools import combinations

fragments = [
    dict(text="abcdefgh", score=0.9),
    dict(text="ijklm", score=0.8),
    dict(text="nopqr", score=0.7),
]
budget, selected, used = 10, [], 0
for item in sorted(fragments, key=lambda item: -item["score"]):
    cost = len(item["text"].encode("utf-8"))
    if used + cost <= budget:
        selected.append(item)
        used += cost
feasible = []
for count in range(len(fragments) + 1):
    for subset in combinations(fragments, count):
        cost = sum(len(item["text"].encode("utf-8")) for item in subset)
        if cost <= budget:
            feasible.append((len(subset), cost))
best_units, best_cost = max(feasible)
print(len(selected), used, best_units, best_cost)

